/**
 * Writes scripts/data/saudi-health-insurance-payer-research.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-saudi-chi-payer-research-cover.mjs.
 *
 *   node scripts/generate-saudi-chi-payer-research-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/saudi-health-insurance-payer-research.json');

export const ARMELA_BELBA_SANITY_ID = '4e924019-dd92-48cf-899b-3bd63c266dd3';

/** Every blogPost field that applies to a healthcare-silo article. */
export const CHI_PAYER_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-saudi-health-insurance-payer-research.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.CHI_PAYER_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.CHI_PAYER_BODY_HTML.split('<h2')[0])
    .replace(/^Saudi health insurance payer research[\s\S]*?This briefing uses only published official sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.CHI_PAYER_META_TITLE,
      metaDescription: mod.CHI_PAYER_META_DESCRIPTION,
      focusKeyword: 'Saudi health insurance payer research',
      keywords: [
        'Saudi health insurance payer research',
        'CHI Dhaman formulary',
        'Council of Health Insurance',
        'Saudi private insurance formulary',
        'NPHIES claims',
        'Insurance Authority Saudi Arabia',
        'CHI Essential Benefit Package',
        'health insurers Saudi Arabia',
      ],
      canonicalUrl: mod.CHI_PAYER_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.CHI_PAYER_META_TITLE,
      ogDescription: mod.CHI_PAYER_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.CHI_PAYER_COVER_IMAGE}`,
        alt: mod.CHI_PAYER_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.CHI_PAYER_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.CHI_PAYER_SLUG },
    excerpt: mod.CHI_PAYER_EXCERPT,
    publishedAt: mod.CHI_PAYER_PUBLISHED_ISO,
    updatedAt: mod.CHI_PAYER_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: ARMELA_BELBA_SANITY_ID,
      name: 'Armela Belba',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.CHI_PAYER_HERO_IMAGE}`,
      alt: mod.CHI_PAYER_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for Saudi health insurance payer research',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.CHI_PAYER_TAGS],
    country: 'Saudi Arabia',
    language: 'en',
    readingTime: mod.CHI_PAYER_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.CHI_PAYER_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.CHI_PAYER_EXECUTIVE_SUMMARY_HTML}\n\n${mod.CHI_PAYER_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What Saudi health insurance payer research should measure',
        type: 'table',
        data: JSON.stringify(
          mod.CHI_PAYER_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'CHI Q3 2025; CHI Dhaman; IA 2024; PPRI 2024; Bupa Arabia FY24',
      },
      portableText(
        firstParagraph ||
          'Saudi health insurance payer research is a private-market access problem before it is an insurance-market-size problem.',
      ),
    ],
    faq: mod.CHI_PAYER_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: [
      'nupco-tender-market-research-saudi-arabia',
      'how-to-choose-healthcare-market-research-agency-saudi-arabia',
      'hematology-market-research-saudi-arabia',
      'who-does-obesity-market-research-saudi-arabia',
    ],
    ctaSection: { ...mod.CHI_PAYER_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.CHI_PAYER_BODY_HTML),
    factCheckedAt: mod.CHI_PAYER_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/saudi-health-insurance-payer-research-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of CHI_PAYER_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
